```python
# Python sync streaming iterator + naive retry
from redwood import Client, APIError
import time

def stream_sync(prompt):
    client = Client()
    backoff = 0.2
    for attempt in range(3):
        try:
            for chunk in client.chat.stream_sync(prompt):
                yield chunk
            return
        except APIError as e:
            if getattr(e, 'status', 0) >= 500:
                time.sleep(backoff)
                backoff *= 2
            else:
                raise
```

