rob: for TypeScript I'd prefer showing AbortController to cancel streaming if needed. I pushed a TS draft to the PR:

```ts
// TS: streaming + AbortController + retry sketch
import { RedwoodClient } from "@redwood/inference";

const client = new RedwoodClient();

export async function streamWithAbort(prompt: string) {
  const controller = new AbortController();
  let backoff = 300;
  for (let attempt = 0; attempt < 4; attempt++) {
    try {
      const stream = await client.chat.stream({ prompt, signal: controller.signal });
      for await (const chunk of stream) {
        console.log(chunk);
      }
      return;
    } catch (err) {
      const status = err?.status ?? 0;
      if (status >= 500) {
        await new Promise(r => setTimeout(r, backoff));
        backoff *= 2;
      } else throw err;
    }
  }
}
```

