mina: Go example uses channels to merge streaming tokens and errors. Short version:

```go
// Go: simple streaming consumer using a channel
package docs

import (
  "context"
  "github.com/redwood/inference-go"
)

func ConsumeStream(ctx context.Context, client *inference.Client, prompt string) (<-chan string, <-chan error) {
  out := make(chan string)
  errs := make(chan error, 1)
  go func() {
    defer close(out)
    defer close(errs)
    stream, err := client.ChatStream(ctx, &inference.ChatRequest{Prompt: prompt})
    if err != nil { errs <- err; return }
    for token := range stream.Tokens() {
      select {
      case out <- token:
      case <-ctx.Done():
        errs <- ctx.Err()
        return
      }
    }
  }()
  return out, errs
}
```

